 const plots=[[-14,0,5,5,4.3,wallA],[-13,-9,6,6,6.5,wallB],[-20,-4,4,5,3.7,wallA],[-18,15,5,4,3.8,wallC],[3,2,6,6,5.6,wallA],[5,12,6,5,3.2,wallB],[16,8,5,7,5.6,wallA],[17,-1,4.5,4.5,4.2,wallC],[3,-13,6,5,4.5,wallB],[16,-13,4,5,3.5,wallA],[-6,-15,4,4,3.2,wallC]];plots.forEach(p=>building(...p));
