 [[-8,3],[-8,1],[-8,-1],[-8,-3],[-8,-5],[1,7],[4,7],[7,7],[13,-7],[13,-9],[-18,10],[-15,13],[1,-7],[4,-7],[7,-7],[-4,13],[-1,13]].forEach(([x,z],i)=>tree(x,z,.75+(i%3)*.15));
 box(6,.03,3,mat(0xbed0b1),-8,.12,15);for(let i=0;i<6;i++)box(.13,.16,2.2,mat(0xeaf0e1),-10+i*.8,.18,15);box(3,.03,5,mat(0xbacdaf),18,.12,-8);
 const robot=new THREE.Group();scene.add(robot);box(1.35,.85,1.6,orange,0,.8,0,robot);box(1.2,.12,1.45,paving,0,1.27,0,robot);box(1.3,.16,1.5,dark,0,.28,0,robot);box(.95,.25,.04,dark,0,.96,.815,robot);for(const x of[-.29,.29])box(.16,.065,.05,mat(0xe2f4ce),x,.97,.85,robot);for(const x of[-.77,.77])for(const z of[-.47,.47]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.23,.23,.18,20),dark);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.29,z);robot.add(wheel);}const antenna=new THREE.Mesh(new THREE.CylinderGeometry(.022,.022,.5,8),dark);antenna.position.set(-.5,1.52,-.5);robot.add(antenna);const antennaTop=new THREE.Mesh(new THREE.SphereGeometry(.06,12,8),orange);antennaTop.position.set(-.5,1.8,-.5);robot.add(antennaTop);
 const packageMesh=new THREE.Group();scene.add(packageMesh);box(.65,.58,.65,parcelMat,0,.29,0,packageMesh);box(.11,.015,.67,mat(0xf2dfc6),0,.587,0,packageMesh);box(.12,.58,.015,mat(0xf2dfc6),0,.29,.335,packageMesh);box(.21,.16,.015,paving,.18,.35,.343,packageMesh);
 const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let drag,lastX,lastY,dragged=false;
 renderer.domElement.addEventListener('pointerdown',e=>{drag=true;dragged=false;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;if(Math.abs(dx)+Math.abs(dy)>2)dragged=true;azimuth-=dx*.006;elevation=Math.max(.35,Math.min(1.35,elevation+dy*.005));lastX=e.clientX;lastY=e.clientY;});renderer.domElement.addEventListener('pointerup',e=>{drag=false;if(dragged)return;const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(pathMeshes)[0];if(hit)onSelect(hit.object.userData.segmentId);});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(2,zoom-e.deltaY*.001));},{passive:false});
 const labelHost=document.getElementById('scene-labels'),labelElements=[];for(const[type,title,subtitle]of[['pickup','Pickup','Market Street · (−12, 8) m'],['destination','Destination','Willow Lane · (10, −10) m'],['robot','R-01 · Idle','']]){const element=document.createElement('div');element.className=`map-label ${type}-label`;element.innerHTML=type==='robot'?title:`<strong><i class="label-dot"></i>${title}</strong><small>${subtitle}</small>`;labelHost.append(element);labelElements.push(element);}
 function updateCamera(){const aspect=innerWidth/innerHeight,span=innerWidth<=800?58:innerWidth<981?50:40;camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2+(innerWidth<=800?5:0);camera.bottom=-span/2+(innerWidth<=800?5:0);camera.zoom=zoom;camera.updateProjectionMatrix();const el=overhead?1.54:elevation;camera.position.set(55*Math.sin(azimuth)*Math.cos(el),55*Math.sin(el),55*Math.cos(azimuth)*Math.cos(el));camera.lookAt(0,0,0);camera.updateMatrixWorld();}
